INSERT INTO public.reviews (id, name, avatar, rating, vehicle, comment, location, date, verified) VALUES ('r1', 'Rajesh Kumar', 'RK', 5, 'Hyundai Creta 2024', 'Buywheels helped me get the best deal on my Creta! The price comparison tool saved me over ₹40,000 compared to what the dealer initially quoted. Excellent service, truly buyer-first!', 'Ranchi', 'June 2024', TRUE);
INSERT INTO public.reviews (id, name, avatar, rating, vehicle, comment, location, date, verified) VALUES ('r2', 'Priya Singh', 'PS', 5, 'Maruti Swift 2024', 'I was confused about which variant to choose. The Buywheels team helped me every step of the way. Got my Swift at the best price in Ranchi, with the Buywheels Welcome Kit thrown in!', 'Jamshedpur', 'May 2024', TRUE);
INSERT INTO public.reviews (id, name, avatar, rating, vehicle, comment, location, date, verified) VALUES ('r3', 'Amit Mahato', 'AM', 5, 'Mahindra XUV700', 'The comparison feature on Buywheels is fantastic. I compared prices across 3 dealers in Dhanbad and saved ₹25,000 on my XUV700. The Buywheels Welcome Kit was a great bonus!', 'Dhanbad', 'June 2024', TRUE);
INSERT INTO public.reviews (id, name, avatar, rating, vehicle, comment, location, date, verified) VALUES ('r4', 'Sunita Devi', 'SD', 4, 'Tata Ace Gold', 'Got my Ace Gold for my business through Buywheels. The finance comparison tool was very helpful. Got a great loan rate through their partner bank. Highly recommend!', 'Bokaro', 'May 2024', TRUE);
INSERT INTO public.reviews (id, name, avatar, rating, vehicle, comment, location, date, verified) VALUES ('r5', 'Vikram Soni', 'VS', 5, 'Mahindra Scorpio-N', 'Outstanding experience! Buywheels guided me through the entire buying process — from comparing variants to finalizing the deal and insurance. Worth every rupee of trust!', 'Ranchi', 'April 2024', TRUE);
INSERT INTO public.reviews (id, name, avatar, rating, vehicle, comment, location, date, verified) VALUES ('r6', 'Deepak Yadav', 'DY', 5, 'Honda City Hybrid', 'Smooth experience from start to finish. The EMI calculator and loan comparison tool are top-notch. Got my City Hybrid at ₹25,000 below the listed price. Thank you Buywheels!', 'Jamshedpur', 'June 2024', TRUE);
