-- ========================================================
-- SUPABASE SETUP & DATA SEEDING
-- ========================================================


-- Drop existing tables if they were created with incompatible schemas (e.g. UUID instead of TEXT)
DROP TABLE IF EXISTS public.vehicle_bookings CASCADE;
DROP TABLE IF EXISTS public.insurance_queries CASCADE;
DROP TABLE IF EXISTS public.job_applications CASCADE;
DROP TABLE IF EXISTS public.loan_applications CASCADE;
DROP TABLE IF EXISTS public.test_drive_bookings CASCADE;
DROP TABLE IF EXISTS public.contact_submissions CASCADE;
DROP TABLE IF EXISTS public.blog_posts CASCADE;
DROP TABLE IF EXISTS public.faqs CASCADE;
DROP TABLE IF EXISTS public.offers CASCADE;
DROP TABLE IF EXISTS public.reviews CASCADE;
DROP TABLE IF EXISTS public.dealer_prices CASCADE;
DROP TABLE IF EXISTS public.dealers CASCADE;
DROP TABLE IF EXISTS public.variants CASCADE;
DROP TABLE IF EXISTS public.vehicles CASCADE;
DROP TABLE IF EXISTS public.brands CASCADE;

-- Create Brands Table
CREATE TABLE IF NOT EXISTS public.brands (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    logo TEXT,
    vehicle_count INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Vehicles Table
CREATE TABLE IF NOT EXISTS public.vehicles (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    category TEXT NOT NULL,
    brand TEXT NOT NULL,
    model TEXT NOT NULL,
    year INTEGER NOT NULL,
    starting_price NUMERIC NOT NULL,
    emi_from NUMERIC NOT NULL,
    images TEXT[] NOT NULL DEFAULT '{}',
    three_sixty_images TEXT[] DEFAULT '{}',
    thumbnail_url TEXT,
    fuel_types TEXT[] NOT NULL DEFAULT '{}',
    transmissions TEXT[] NOT NULL DEFAULT '{}',
    mileage TEXT,
    features TEXT[] DEFAULT '{}',
    colors TEXT[] DEFAULT '{}',
    rating NUMERIC NOT NULL DEFAULT 0,
    review_count INTEGER NOT NULL DEFAULT 0,
    is_new BOOLEAN DEFAULT false,
    is_best_seller BOOLEAN DEFAULT false,
    is_ev BOOLEAN DEFAULT false,
    seating_capacity INTEGER,
    boot_space_l INTEGER,
    engine_cc INTEGER,
    power_bhp NUMERIC,
    torque_nm NUMERIC,
    safety_rating INTEGER,
    description TEXT,
    pros TEXT[] DEFAULT '{}',
    cons TEXT[] DEFAULT '{}',
    ground_clearance INTEGER,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Variants Table
CREATE TABLE IF NOT EXISTS public.variants (
    id TEXT PRIMARY KEY,
    vehicle_id TEXT REFERENCES public.vehicles(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    price NUMERIC NOT NULL,
    fuel_type TEXT NOT NULL,
    transmission TEXT NOT NULL,
    engine_cc INTEGER,
    power_bhp NUMERIC,
    torque_nm NUMERIC,
    mileage_kmpl NUMERIC,
    range_km NUMERIC,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Dealers Table
CREATE TABLE IF NOT EXISTS public.dealers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    brand TEXT,
    brands TEXT[] NOT NULL DEFAULT '{}',
    location TEXT NOT NULL,
    city TEXT NOT NULL,
    address TEXT,
    phone TEXT,
    rating NUMERIC NOT NULL DEFAULT 0,
    review_count INTEGER NOT NULL DEFAULT 0,
    image TEXT,
    open_hours TEXT,
    lat NUMERIC,
    lng NUMERIC,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Dealer Prices Table
CREATE TABLE IF NOT EXISTS public.dealer_prices (
    vehicle_id TEXT REFERENCES public.vehicles(id) ON DELETE CASCADE,
    dealer_id TEXT REFERENCES public.dealers(id) ON DELETE CASCADE,
    price NUMERIC NOT NULL,
    discount NUMERIC DEFAULT 0,
    PRIMARY KEY (vehicle_id, dealer_id)
);

-- Create Reviews Table
CREATE TABLE IF NOT EXISTS public.reviews (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    avatar TEXT,
    rating NUMERIC NOT NULL DEFAULT 0,
    vehicle TEXT NOT NULL,
    comment TEXT,
    location TEXT,
    date TEXT,
    verified BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Offers Table
CREATE TABLE IF NOT EXISTS public.offers (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    description TEXT,
    discount TEXT,
    valid_till TEXT,
    category TEXT,
    brand TEXT,
    image TEXT,
    code TEXT,
    type TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create FAQs Table
CREATE TABLE IF NOT EXISTS public.faqs (
    id TEXT PRIMARY KEY,
    question TEXT NOT NULL,
    answer TEXT NOT NULL,
    category TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Blog Posts Table
CREATE TABLE IF NOT EXISTS public.blog_posts (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    excerpt TEXT,
    image TEXT,
    category TEXT,
    date TEXT,
    read_time TEXT,
    slug TEXT NOT NULL UNIQUE,
    meta_title TEXT,
    meta_description TEXT,
    content JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable Row Level Security (RLS)
ALTER TABLE public.brands ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dealers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dealer_prices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.faqs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;

-- Drop existing policies if any to avoid errors on re-run
DROP POLICY IF EXISTS "Allow public read access" ON public.brands;
DROP POLICY IF EXISTS "Allow public read access" ON public.vehicles;
DROP POLICY IF EXISTS "Allow public read access" ON public.variants;
DROP POLICY IF EXISTS "Allow public read access" ON public.dealers;
DROP POLICY IF EXISTS "Allow public read access" ON public.dealer_prices;
DROP POLICY IF EXISTS "Allow public read access" ON public.reviews;
DROP POLICY IF EXISTS "Allow public read access" ON public.offers;
DROP POLICY IF EXISTS "Allow public read access" ON public.faqs;
DROP POLICY IF EXISTS "Allow public read access" ON public.blog_posts;

-- Create policies for public reading
CREATE POLICY "Allow public read access" ON public.brands FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.vehicles FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.variants FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.dealers FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.dealer_prices FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.reviews FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.offers FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.faqs FOR SELECT TO public USING (true);
CREATE POLICY "Allow public read access" ON public.blog_posts FOR SELECT TO public USING (true);

-- Clear existing data (to allow clean seeding)
TRUNCATE TABLE public.variants CASCADE;
TRUNCATE TABLE public.dealer_prices CASCADE;
TRUNCATE TABLE public.vehicles CASCADE;
TRUNCATE TABLE public.brands CASCADE;
TRUNCATE TABLE public.dealers CASCADE;
TRUNCATE TABLE public.reviews CASCADE;
TRUNCATE TABLE public.offers CASCADE;
TRUNCATE TABLE public.faqs CASCADE;
TRUNCATE TABLE public.blog_posts CASCADE;


