-- ========================================================
-- FORM SUBMISSIONS TABLES
-- ========================================================

-- Create Contact Submissions Table
CREATE TABLE IF NOT EXISTS public.contact_submissions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    email TEXT,
    phone TEXT NOT NULL,
    subject TEXT NOT NULL,
    message TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Test Drive Bookings Table
CREATE TABLE IF NOT EXISTS public.test_drive_bookings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vehicle_id TEXT REFERENCES public.vehicles(id) ON DELETE SET NULL,
    city TEXT NOT NULL,
    booking_date DATE NOT NULL,
    time_slot TEXT NOT NULL,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    email TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Loan Applications Table
CREATE TABLE IF NOT EXISTS public.loan_applications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL,
    phone TEXT NOT NULL,
    email TEXT,
    employment TEXT NOT NULL,
    monthly_income NUMERIC NOT NULL,
    vehicle_type TEXT NOT NULL,
    preferred_bank TEXT NOT NULL,
    loan_amount NUMERIC NOT NULL,
    estimated_emi NUMERIC NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Job Applications Table
CREATE TABLE IF NOT EXISTS public.job_applications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    position TEXT NOT NULL,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT NOT NULL,
    note TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Create Insurance Queries Table
CREATE TABLE IF NOT EXISTS public.insurance_queries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vehicle_id TEXT REFERENCES public.vehicles(id) ON DELETE SET NULL,
    registration_year TEXT NOT NULL,
    claims_past_year TEXT NOT NULL,
    comprehensive_premium NUMERIC NOT NULL,
    third_party_premium NUMERIC NOT NULL,
    idv NUMERIC NOT NULL,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable Row Level Security (RLS) for all submission tables
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.test_drive_bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.loan_applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.insurance_queries ENABLE ROW LEVEL SECURITY;

-- Create Vehicle Bookings Table (for the Book Now modal)
CREATE TABLE IF NOT EXISTS public.vehicle_bookings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vehicle_id TEXT REFERENCES public.vehicles(id) ON DELETE SET NULL,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    email TEXT,
    city TEXT NOT NULL,
    purpose TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS for vehicle_bookings
ALTER TABLE public.vehicle_bookings ENABLE ROW LEVEL SECURITY;

-- Drop existing policies if they exist to avoid duplication errors on re-run
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.contact_submissions;
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.test_drive_bookings;
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.loan_applications;
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.job_applications;
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.insurance_queries;
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.vehicle_bookings;
DROP POLICY IF EXISTS "Allow anonymous inserts" ON public.reviews;

-- Allow anonymous users to INSERT submissions, but NOT SELECT them (keeps PII data private)
CREATE POLICY "Allow anonymous inserts" ON public.contact_submissions FOR INSERT TO anon WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts" ON public.test_drive_bookings FOR INSERT TO anon WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts" ON public.loan_applications FOR INSERT TO anon WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts" ON public.job_applications FOR INSERT TO anon WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts" ON public.insurance_queries FOR INSERT TO anon WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts" ON public.vehicle_bookings FOR INSERT TO anon WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts" ON public.reviews FOR INSERT TO anon WITH CHECK (true);

-- Enable RLS and allow full access on public catalog tables
ALTER TABLE public.brands ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dealers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dealer_prices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.faqs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public full access" ON public.brands;
DROP POLICY IF EXISTS "Allow public full access" ON public.vehicles;
DROP POLICY IF EXISTS "Allow public full access" ON public.variants;
DROP POLICY IF EXISTS "Allow public full access" ON public.dealers;
DROP POLICY IF EXISTS "Allow public full access" ON public.dealer_prices;
DROP POLICY IF EXISTS "Allow public full access" ON public.offers;
DROP POLICY IF EXISTS "Allow public full access" ON public.faqs;
DROP POLICY IF EXISTS "Allow public full access" ON public.blog_posts;

CREATE POLICY "Allow public full access" ON public.brands FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.variants FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.dealers FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.dealer_prices FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.offers FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.faqs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public full access" ON public.blog_posts FOR ALL USING (true) WITH CHECK (true);
